@sig trait TemperatureEvidenceQualification_Api {
  def id: Art.BridgeId
  def rawTemperature_Id : Art.PortId
  def assessmentForRecovery_Id : Art.PortId
  def assessmentForArbitration_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var assessmentForRecovery: Vehicle_Temperature_Health_Supervisor.TemperatureAssessment.Type = $

  def put_assessmentForRecovery(value : Vehicle_Temperature_Health_Supervisor.TemperatureAssessment.Type) : Unit = {
    Contract(
      Modifies(assessmentForRecovery),
      Ensures(
        assessmentForRecovery == value
      )
    )
    Spec {
      assessmentForRecovery = value
    }

    Art.putValue(assessmentForRecovery_Id, Vehicle_Temperature_Health_Supervisor.TemperatureAssessment_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var assessmentForArbitration: Vehicle_Temperature_Health_Supervisor.TemperatureAssessment.Type = $

  def put_assessmentForArbitration(value : Vehicle_Temperature_Health_Supervisor.TemperatureAssessment.Type) : Unit = {
    Contract(
      Modifies(assessmentForArbitration),
      Ensures(
        assessmentForArbitration == value
      )
    )
    Spec {
      assessmentForArbitration = value
    }

    Art.putValue(assessmentForArbitration_Id, Vehicle_Temperature_Health_Supervisor.TemperatureAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class TemperatureEvidenceQualification_Initialization_Api (
  val id: Art.BridgeId,
  val rawTemperature_Id : Art.PortId,
  val assessmentForRecovery_Id : Art.PortId,
  val assessmentForArbitration_Id : Art.PortId) extends TemperatureEvidenceQualification_Api

@datatype class TemperatureEvidenceQualification_Operational_Api (
  val id: Art.BridgeId,
  val rawTemperature_Id : Art.PortId,
  val assessmentForRecovery_Id : Art.PortId,
  val assessmentForArbitration_Id : Art.PortId) extends TemperatureEvidenceQualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var rawTemperature: Vehicle_Temperature_Health_Supervisor.TemperatureSample = $

  def get_rawTemperature() : Option[Vehicle_Temperature_Health_Supervisor.TemperatureSample] = {
    Contract(
      Ensures(
        Res == Some(rawTemperature)
      )
    )
    val value : Option[Vehicle_Temperature_Health_Supervisor.TemperatureSample] = Art.getValue(rawTemperature_Id) match {
      case Some(Vehicle_Temperature_Health_Supervisor.TemperatureSample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port rawTemperature.  Expecting 'Vehicle_Temperature_Health_Supervisor.TemperatureSample_Payload' but received ${v}")
